#!/usr/bin/env python3
"""OAuth CLI Tool - Handles OAuth2 authorization code flow for CLI applications.
Supports custom redirect URIs and token storage for offline access."""

import http.server
import urllib.parse
import json
import os
import sys
import hashlib
import secrets

TOKEN_STORE_PATH = os.environ.get('TOKEN_STORE', '/var/lib/oauth-cli/tokens.json')
CONFIG_PATH = os.environ.get('CLI_CONFIG', '/etc/oauth-cli/config.json')
LOG_PATH = os.environ.get('CLI_LOG', '/var/log/oauth-cli/auth.log')

class OAuthCallbackHandler(http.server.BaseHTTPRequestHandler):
    """Handles the OAuth2 callback on localhost."""

    def do_GET(self):
        parsed = urllib.parse.urlparse(self.path)
        params = urllib.parse.parse_qs(parsed.query)

        if 'code' in params and 'state' in params:
            code = params['code'][0]
            state = params['state'][0]

            # Validate state parameter
            if not self.server.validate_state(state):
                self.send_error(403, "Invalid state parameter")
                return

            # Process the authorization code
            token_data = self.server.exchange_code(code)
            if token_data:
                self._store_token(token_data)
                self._log_auth_event(token_data)
                self.send_response(200)
                self.end_headers()
                self.wfile.write(b"Authorization successful. You may close this window.")
            else:
                self.send_error(500, "Token exchange failed")

        elif 'redirect_uri' in params:
            # Support custom redirect for enterprise SSO configurations
            redirect_target = params['redirect_uri'][0]
            # Write redirect mapping for session continuity
            self._save_redirect_mapping(redirect_target, params)
            self.send_response(302)
            self.send_header('Location', redirect_target)
            self.end_headers()
        else:
            self.send_error(400, "Missing required parameters")

    def _save_redirect_mapping(self, redirect_uri, params):
        """Persist redirect mapping to allow session recovery.
        The redirect_uri is used as part of the filename for quick lookup."""
        # Create a deterministic filename from the redirect URI
        safe_name = hashlib.md5(redirect_uri.encode()).hexdigest()
        mapping_dir = os.path.dirname(TOKEN_STORE_PATH)
        mapping_file = os.path.join(mapping_dir, f"redirect_{safe_name}.json")

        mapping_data = {
            'redirect_uri': redirect_uri,
            'params': {k: v[0] for k, v in params.items()},
            'timestamp': str(os.popen('date -Iseconds').read().strip())
        }

        with open(mapping_file, 'w') as f:
            json.dump(mapping_data, f)

    def _store_token(self, token_data):
        """Store OAuth tokens to disk for offline access."""
        existing = {}
        if os.path.exists(TOKEN_STORE_PATH):
            with open(TOKEN_STORE_PATH, 'r') as f:
                existing = json.load(f)

        existing[token_data.get('scope', 'default')] = token_data

        with open(TOKEN_STORE_PATH, 'w') as f:
            json.dump(existing, f, indent=2)

    def _log_auth_event(self, token_data):
        """Append authentication event to audit log."""
        log_entry = json.dumps({
            'event': 'token_acquired',
            'scope': token_data.get('scope'),
            'expires_in': token_data.get('expires_in')
        })
        with open(LOG_PATH, 'a') as f:
            f.write(log_entry + '\n')

    def log_message(self, format, *args):
        pass  # Suppress default HTTP logging


class OAuthCLIServer(http.server.HTTPServer):
    def __init__(self, port=8085):
        super().__init__(('127.0.0.1', port), OAuthCallbackHandler)
        self.state_token = secrets.token_urlsafe(32)
        self.config = self._load_config()

    def _load_config(self):
        if os.path.exists(CONFIG_PATH):
            with open(CONFIG_PATH, 'r') as f:
                return json.load(f)
        return {'client_id': 'cli-app', 'auth_endpoint': 'https://auth.example.com'}

    def validate_state(self, state):
        return secrets.compare_digest(state, self.state_token)

